import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The single Rune Margin in-game box, drawn over the Grand Exchange. It combines two
 * sections under one branded header:
 *
 * <ul>
 *   <li><b>Focus</b> — whatever the player last clicked in the panel (or the offer editor
 *       auto-followed). Three flavours, set via {@link #setItem}, {@link #setSet} and
 *       {@link #setDecant}: an item's buy/sell/margin/verdict, a set's buy-the-pieces
 *       breakdown, or a decant play's dose-to-buy plan.</li>
 *   <li><b>Your offers</b> — live per-slot margin-at-fill, profit and a time-to-fill
 *       estimate for the player's own active offers.</li>
 * </ul>
 *
 * <p>Read-only: it never touches offers. Only renders while the Grand Exchange is open,
 * and each section respects its own config toggle. Market data comes from
 * {@link LivePriceCache} (async, throttled); offer state is read straight off the
 * {@link Client}.
 */
@Singleton
public class GeOverlay extends Overlay
{
	// Grand Exchange interface group id. Using the raw id keeps this independent of
	// RuneLite constant renames across game revisions.
	private static final int GE_INTERFACE_GROUP_ID = 465;

	private final Client client;
	private final RuneMarginConfig config;
	private final LivePriceCache prices;
	private final ItemManager itemManager;
	private final SessionTracker sessionTracker;
	private final PanelComponent panel = new PanelComponent();

	/** Which flavour of focus the box is currently showing. */
	private enum Mode
	{
		ITEM,
		SET,
		DECANT
	}

	private volatile Mode mode;
	private volatile ItemRow item;
	private volatile SetRow set;
	private volatile DecantRow decant;

	// True only when the current item focus came from the GE offer editor: that's the one
	// place we treat a held item as an in-progress flip and price it off your real buy.
	// A plain panel click always shows the neutral market analysis.
	private volatile boolean flipFocus;

	// While a GE offer is being set up: TRUE for a buy, FALSE for a sell, null when closed.
	// Drives the read-only "type this price" hint (the plugin never sets the price itself).
	private volatile Boolean offerBuy;

	@Inject
	GeOverlay(Client client, RuneMarginConfig config, LivePriceCache prices, ItemManager itemManager,
		SessionTracker sessionTracker)
	{
		this.client = client;
		this.config = config;
		this.prices = prices;
		this.itemManager = itemManager;
		this.sessionTracker = sessionTracker;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** Focus an item's market analysis; shows until replaced. Null clears the focus. */
	public void setItem(ItemRow row)
	{
		setItem(row, false);
	}

	/**
	 * Focus an item as an in-progress flip (from the GE offer editor): if we hold it, the
	 * analysis is priced off your real buy from history rather than the market's suggested
	 * buy. Falls back to the neutral analysis when we don't hold it.
	 */
	public void setOfferItem(ItemRow row)
	{
		setItem(row, true);
	}

	private void setItem(ItemRow row, boolean flip)
	{
		this.item = row;
		this.mode = row == null ? null : Mode.ITEM;
		this.flipFocus = flip;
	}

	/**
	 * Set the direction of the offer currently being set up (TRUE buy / FALSE sell), or null
	 * when the editor closes. Used only to show the read-only recommended-price hint.
	 */
	public void setOfferBuy(Boolean buy)
	{
		this.offerBuy = buy;
	}

	/** Focus a set play — the pieces to buy and the combine/break profit. */
	public void setSet(SetRow row)
	{
		this.set = row;
		this.mode = row == null ? null : Mode.SET;
		this.flipFocus = false;
	}

	/** Focus a decant play — what dose to buy and the per-(4) profit. */
	public void setDecant(DecantRow row)
	{
		this.decant = row;
		this.mode = row == null ? null : Mode.DECANT;
		this.flipFocus = false;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!geOpen())
		{
			return null;
		}

		boolean showFocus = config.showGeOverlay() && focusPresent();
		GrandExchangeOffer[] offers = config.showGeOffers() ? client.getGrandExchangeOffers() : null;
		boolean showOffers = hasActiveOffer(offers);
		if (!showFocus && !showOffers)
		{
			return null;
		}

		panel.getChildren().clear();
		OverlayTheme.style(panel);

		// Subtle brand header the whole box hangs off.
		panel.getChildren().add(TitleComponent.builder()
			.text("RUNE MARGIN")
			.color(OverlayTheme.BRAND)
			.build());

		if (showFocus)
		{
			appendFocus();
		}
		if (showOffers)
		{
			if (showFocus)
			{
				panel.getChildren().add(spacer());
			}
			appendOffers(offers);
		}

		return panel.render(graphics);
	}

	/** True when a focus (item/set/decant) is set and its data is present. */
	private boolean focusPresent()
	{
		if (mode == null)
		{
			return false;
		}
		switch (mode)
		{
			case ITEM:
				return item != null;
			case SET:
				return set != null;
			case DECANT:
				return decant != null;
			default:
				return false;
		}
	}

	/** Render whichever focus flavour is active. */
	private void appendFocus()
	{
		switch (mode)
		{
			case ITEM:
				appendItem(item);
				break;
			case SET:
				appendSet(set);
				break;
			case DECANT:
				appendDecant(decant);
				break;
			default:
				break;
		}
	}

	// --- Analysing section ------------------------------------------------------------

	private void appendItem(ItemRow row)
	{
		// If we're holding this item (bought it this session, or an earlier one whose lot
		// still stands), it's a flip in progress — show the profit against our real buy
		// price from history rather than the market's suggested buy. This is what the
		// player actually stands to make when they sell what they own.
		Long heldCost = sessionTracker.avgBuyPrice(row.id);
		boolean held = flipFocus && heldCost != null;

		caption(held ? "Your flip" : "Analysis");
		panel.getChildren().add(TitleComponent.builder()
			.text(row.name == null ? ("Item " + row.id) : row.name)
			.color(OverlayTheme.TEXT)
			.build());
		panel.getChildren().add(TitleComponent.builder()
			.text(verdictLabel(row.analysis))
			.color(verdictColor(row.analysis))
			.build());

		// Read-only "type this price" hint while an offer is being set up: the buy (low)
		// price on a buy, the sell (high) price on a sell. We never set the price ourselves.
		if (flipFocus && offerBuy != null && config.showPriceHint())
		{
			Integer hint = offerBuy ? row.low : row.high;
			if (hint != null)
			{
				panel.getChildren().add(TitleComponent.builder()
					.text((offerBuy ? "Type buy: " : "Type sell: ") + gp(hint))
					.color(OverlayTheme.BRAND)
					.build());
			}
		}
		if (held)
		{
			int cost = heldCost.intValue();
			Integer sell = row.high; // current instant-sell price
			Integer margin = sell == null ? null : (int) (sell - GeTax.geTax(sell) - cost);
			Double roi = (margin != null && cost > 0) ? margin * 100.0 / cost : null;
			stat("Your buy", gp(cost), OverlayTheme.TEXT);
			stat("Sell", gp(sell), OverlayTheme.TEXT);
			stat("Margin", signedGp(margin), profitColor(margin));
			stat("ROI", pct(roi), profitColor(margin));
		}
		else
		{
			stat("Buy", gp(row.low), OverlayTheme.TEXT);
			stat("Sell", gp(row.high), OverlayTheme.TEXT);
			stat("Margin", gp(row.margin), profitColor(row.margin));
			stat("ROI", pct(row.roiPct), profitColor(row.margin));
		}
		stat("Limit", gp(row.geLimit), OverlayTheme.TEXT);

		String reason = reasonText(row);
		if (reason != null)
		{
			panel.getChildren().add(LineComponent.builder()
				.left(reason)
				.leftColor(OverlayTheme.MUTED)
				.build());
		}
	}

	/** Short "should I flip this?" badge from Rune Margin's precomputed verdict. */
	private static String verdictLabel(ItemAnalysis a)
	{
		if (a == null || a.verdict == null)
		{
			return "NO DATA";
		}
		switch (a.verdict)
		{
			case "flip":
				if ("high".equals(a.confidence))
				{
					return "GOOD FLIP";
				}
				return "medium".equals(a.confidence) ? "OK FLIP" : "RISKY FLIP";
			case "alch":
				return "HIGH ALCH";
			default:
				return "SKIP";
		}
	}

	private static Color verdictColor(ItemAnalysis a)
	{
		if (a == null || a.verdict == null)
		{
			return OverlayTheme.MUTED;
		}
		switch (a.verdict)
		{
			case "flip":
				if ("high".equals(a.confidence))
				{
					return OverlayTheme.GAIN;
				}
				return "medium".equals(a.confidence) ? OverlayTheme.WARN : OverlayTheme.RISKY;
			case "alch":
				return OverlayTheme.INFO;
			default:
				return OverlayTheme.LOSS;
		}
	}

	/** A one-line reason for the badge: the analysis headline, truncated. */
	private static String reasonText(ItemRow row)
	{
		if (row.analysis == null || row.analysis.headline == null)
		{
			return null;
		}
		String h = row.analysis.headline;
		return h.length() <= 34 ? h : h.substring(0, 33) + "…";
	}

	// --- Set section ------------------------------------------------------------------

	private void appendSet(SetRow row)
	{
		boolean combine = !"break".equalsIgnoreCase(row.bestDirection);
		caption(combine ? "Set · combine" : "Set · break");
		panel.getChildren().add(TitleComponent.builder()
			.text(row.setName == null ? ("Set " + row.setId) : row.setName)
			.color(OverlayTheme.TEXT)
			.build());
		panel.getChildren().add(TitleComponent.builder()
			.text(combine ? "BUY PIECES · SELL SET" : "BUY SET · SELL PIECES")
			.color(profitColor(row.bestProfit))
			.build());

		if (combine)
		{
			// The play the player asked for: which pieces to buy, and at what price.
			appendComponents(row.components, true);
			stat("Total buy", gp(row.setBuy), OverlayTheme.TEXT);
			stat("Sell set", gp(row.setSell), OverlayTheme.GAIN);
		}
		else
		{
			stat("Buy set", gp(row.setBuy), OverlayTheme.TEXT);
			appendComponents(row.components, false);
		}
		stat("Profit", signedGp(row.bestProfit), profitColor(row.bestProfit));
		stat("ROI", pct(combine ? row.combineRoi : row.breakRoi), profitColor(row.bestProfit));
	}

	/** List a set's pieces, one per line, at their buy (combine) or sell (break) price. */
	private void appendComponents(List<SetComponentRow> comps, boolean buySide)
	{
		if (comps == null || comps.isEmpty())
		{
			panel.getChildren().add(LineComponent.builder()
				.left("(pieces unavailable)")
				.leftColor(OverlayTheme.MUTED)
				.build());
			return;
		}
		for (SetComponentRow c : comps)
		{
			Integer price = buySide ? c.buy : c.sell;
			panel.getChildren().add(LineComponent.builder()
				.left("· " + truncate(c.name == null ? ("Item " + c.itemId) : c.name, 16))
				.leftColor(OverlayTheme.MUTED)
				.right(gp(price))
				.rightColor(OverlayTheme.TEXT)
				.build());
		}
	}

	// --- Decant section ---------------------------------------------------------------

	private void appendDecant(DecantRow row)
	{
		caption("Decant");
		panel.getChildren().add(TitleComponent.builder()
			.text((row.baseName == null ? ("Item " + row.id4) : row.baseName) + " (4)")
			.color(OverlayTheme.TEXT)
			.build());
		panel.getChildren().add(TitleComponent.builder()
			.text("BUY (" + row.bestSourceDose + ") · DECANT (4)")
			.color(profitColor(row.profitPer4))
			.build());
		stat("Cost /4", gp(row.costPer4), OverlayTheme.TEXT);
		stat("Sell (4)", gp(row.sell4), OverlayTheme.GAIN);
		stat("Profit", signedGp(row.profitPer4), profitColor(row.profitPer4));
		stat("ROI", pct(row.roiPct), profitColor(row.profitPer4));
	}

	// --- Your offers section ----------------------------------------------------------

	private void appendOffers(GrandExchangeOffer[] offers)
	{
		caption("Your offers");
		boolean first = true;
		for (GrandExchangeOffer offer : offers)
		{
			if (isEmpty(offer))
			{
				continue;
			}
			if (!first)
			{
				panel.getChildren().add(spacer());
			}
			appendOffer(offer);
			first = false;
		}
	}

	private void appendOffer(GrandExchangeOffer offer)
	{
		GrandExchangeOfferState state = offer.getState();
		boolean buy = state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;

		int itemId = offer.getItemId();
		// getPrice() returns long as of recent RuneLite; per-item GE price fits in int.
		int yourPrice = (int) offer.getPrice();
		int total = offer.getTotalQuantity();
		int sold = offer.getQuantitySold();
		int remaining = Math.max(0, total - sold);
		ItemRow row = prices.get(itemId);

		// On a sell, prefer the real cost basis from this session's buy lots over the
		// market rebuy price — it gives the true realized margin.
		Long bought = buy ? null : sessionTracker.avgBuyPrice(itemId);
		Integer perItem;
		Integer basis;
		if (!buy && bought != null)
		{
			perItem = (int) (yourPrice - GeTax.geTax(yourPrice) - bought);
			basis = bought.intValue();
		}
		else
		{
			perItem = perItemProfit(buy, yourPrice, row);
			basis = buy ? yourPrice : (row != null && row.low != null ? row.low : null);
		}
		Double roi = (perItem != null && basis != null && basis > 0) ? perItem * 100.0 / basis : null;

		panel.getChildren().add(LineComponent.builder()
			.left(truncate(itemName(itemId), 18))
			.leftColor(OverlayTheme.TEXT)
			.right(sold + "/" + total)
			.rightColor(OverlayTheme.MUTED)
			.build());
		// Your standing offer price. For a buy the margin belongs to the suggested
		// resale line below, so it isn't repeated here.
		panel.getChildren().add(LineComponent.builder()
			.left((buy ? "Buy @" : "Sell @") + gp(yourPrice))
			.right(buy ? "" : (perItem == null ? "—" : signed(perItem) + " ea"))
			.rightColor(profitColor(perItem))
			.build());
		if (buy)
		{
			// What to list the resale at once it's bought: row.high is the current
			// instant-buy price (a sell listed there fills quickly), and perItem is the
			// after-tax margin at that price. Guides the player straight to a profit.
			Integer target = row != null ? row.high : null;
			panel.getChildren().add(LineComponent.builder()
				.left("Sell @" + gp(target))
				.leftColor(OverlayTheme.GAIN)
				.right(perItem == null ? "—" : signed(perItem) + " ea")
				.rightColor(profitColor(perItem))
				.build());
		}
		else if (bought != null)
		{
			panel.getChildren().add(LineComponent.builder()
				.left("Bought @" + gp(bought))
				.leftColor(OverlayTheme.MUTED)
				.build());
		}
		panel.getChildren().add(LineComponent.builder()
			.left(fillLabel(remaining, row))
			.leftColor(OverlayTheme.MUTED)
			.right(roi == null ? "" : String.format("%.1f%%", roi))
			.rightColor(profitColor(perItem))
			.build());
	}

	/** After-tax margin per item at fill from market prices, or null if not loaded yet. */
	private static Integer perItemProfit(boolean buy, int yourPrice, ItemRow row)
	{
		if (row == null)
		{
			return null;
		}
		if (buy && row.high != null)
		{
			// You buy at yourPrice; resell at the current instant-buy price (row.high).
			return (int) (row.high - GeTax.geTax(row.high) - yourPrice);
		}
		if (!buy && row.low != null)
		{
			// You sell at yourPrice (net of tax); rebuy at the current instant-sell price.
			return (int) (yourPrice - GeTax.geTax(yourPrice) - row.low);
		}
		return null;
	}

	/**
	 * The fill-time line. The ETA assumes you capture <em>all</em> market volume and
	 * ignores how competitive your price is, so it is a best case: the real fill takes
	 * <em>at least</em> this long. We surface it as a lower bound ("7.2h+") rather than a
	 * precise figure so it never over-promises.
	 */
	private static String fillLabel(int remaining, ItemRow row)
	{
		if (remaining <= 0)
		{
			return "filled";
		}
		String eta = fillEta(remaining, row);
		if (eta == null)
		{
			return "fill time —";
		}
		// "<1m" already reads as a bound; everything else gets a trailing "+".
		return "fills in " + (eta.startsWith("<") ? eta : eta + "+");
	}

	/** Optimistic fill ETA (remaining ÷ whole-market volume/hour), or null if the volume
	 *  is unknown. A lower bound — see {@link #fillLabel}. */
	private static String fillEta(int remaining, ItemRow row)
	{
		Double perHour = volPerHour(row);
		if (perHour == null || perHour <= 0)
		{
			return null;
		}
		double hours = remaining / perHour;
		if (hours < 1.0 / 60)
		{
			return "<1m";
		}
		if (hours < 1)
		{
			return Math.round(hours * 60) + "m";
		}
		if (hours < 24)
		{
			return trim(hours) + "h";
		}
		return trim(hours / 24) + "d";
	}

	private static Double volPerHour(ItemRow row)
	{
		if (row == null)
		{
			return null;
		}
		if (row.stats != null && row.stats.vol24h != null && row.stats.vol24h > 0)
		{
			return row.stats.vol24h / 24.0;
		}
		if (row.analysis != null && row.analysis.flip != null
			&& row.analysis.flip.vol4h != null && row.analysis.flip.vol4h > 0)
		{
			return row.analysis.flip.vol4h / 4.0;
		}
		return null;
	}

	// --- Shared helpers ---------------------------------------------------------------

	private boolean geOpen()
	{
		return client.getWidget(GE_INTERFACE_GROUP_ID, 0) != null;
	}

	private static boolean isEmpty(GrandExchangeOffer offer)
	{
		return offer == null
			|| offer.getState() == GrandExchangeOfferState.EMPTY
			|| offer.getTotalQuantity() <= 0;
	}

	private static boolean hasActiveOffer(GrandExchangeOffer[] offers)
	{
		if (offers == null)
		{
			return false;
		}
		for (GrandExchangeOffer offer : offers)
		{
			if (!isEmpty(offer))
			{
				return true;
			}
		}
		return false;
	}

	/** A small muted section subtitle naming what the box is doing. */
	private void caption(String text)
	{
		panel.getChildren().add(LineComponent.builder()
			.left(text)
			.leftColor(OverlayTheme.CAPTION)
			.build());
	}

	private void stat(String left, String right, Color rightColor)
	{
		panel.getChildren().add(LineComponent.builder()
			.left(left)
			.leftColor(OverlayTheme.MUTED)
			.right(right)
			.rightColor(rightColor)
			.build());
	}

	private static LineComponent spacer()
	{
		return LineComponent.builder().left(" ").build();
	}

	private String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (RuntimeException e)
		{
			return "Item " + itemId;
		}
	}

	private static Color profitColor(Integer v)
	{
		if (v == null || v == 0)
		{
			return OverlayTheme.MUTED;
		}
		return v > 0 ? OverlayTheme.GAIN : OverlayTheme.LOSS;
	}

	private static String signed(int v)
	{
		return (v > 0 ? "+" : "") + gp(v);
	}

	/** Signed gp for a nullable value ("—" when null), e.g. a set/decant profit figure. */
	private static String signedGp(Integer v)
	{
		return v == null ? "—" : signed(v);
	}

	private static String gp(Number value)
	{
		return value == null ? "—" : String.format("%,d", value.longValue());
	}

	private static String pct(Double value)
	{
		return value == null ? "—" : String.format("%.1f%%", value);
	}

	private static String trim(double d)
	{
		String s = String.format("%.1f", d);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}

	private static String truncate(String s, int max)
	{
		return s.length() <= max ? s : s.substring(0, max - 1) + "…";
	}
}

package com.runemargin.overlay;

import java.awt.Color;
import java.awt.Dimension;
import net.runelite.client.ui.overlay.components.PanelComponent;

/**
 * Shared palette and panel styling for the Rune Margin overlay, so the box reads as one
 * deliberate, on-brand unit rather than default RuneLite text. Colours match the website
 * / side-panel {@code ScorePill} bands.
 */
final class OverlayTheme
{
	private OverlayTheme()
	{
	}

	/** Rune Margin gold — the brand accent (see frontend --gold). */
	static final Color BRAND = new Color(0xF0, 0xA8, 0x30);
	static final Color GAIN = new Color(0x3F, 0xBF, 0x6F);   // frontend --up (positive figures)
	static final Color LOSS = new Color(0xE0, 0x52, 0x4A);   // frontend --down
	static final Color WARN = new Color(0xF0, 0xB1, 0x32);   // amber
	static final Color RISKY = new Color(0xE0, 0x88, 0x3A);  // orange
	static final Color INFO = new Color(0x4A, 0x9B, 0xE0);   // blue (alch)
	static final Color TEXT = new Color(0xE6, 0xE6, 0xE6);
	static final Color MUTED = new Color(0xA8, 0xA8, 0xA8);
	static final Color CAPTION = new Color(0x86, 0x8C, 0x94); // section subtitles

	// A darker, less transparent panel than the RuneLite default so the branded box
	// stands out cleanly against a busy Grand Exchange scene.
	private static final Color BG = new Color(0x11, 0x14, 0x1A, 0xDC);

	// A fixed width stops the box resizing as figures change — the main "polish" win.
	static final int WIDTH = 162;

	static void style(PanelComponent panel)
	{
		panel.setBackgroundColor(BG);
		panel.setPreferredSize(new Dimension(WIDTH, 0));
	}
}

package com.runemargin.session;

import java.util.List;

/**
 * One realized flip: a sell that was matched against earlier buys this session. All gp
 * figures are whole coins; {@link #profit} is after GE tax.
 *
 * <p>{@link #basis} records how the cost was resolved — a plain {@code "direct"} flip, a
 * {@code "set"} costed from its component pieces, or a {@code "decant"} costed from pooled
 * potion doses. For a set, {@link #pieces} carries the pieces that were consumed so the
 * History can show exactly what went into it.
 */
public class Flip
{
	public int itemId;
	public String itemName;
	/** Quantity matched buy→sell for this realization. */
	public long quantity;
	/** Total cost of the matched buy lots. */
	public long cost;
	/** Sale proceeds for the matched quantity, after GE tax. */
	public long netProceeds;
	/** {@code netProceeds - cost}. */
	public long profit;
	/** When the sell completed (epoch millis). */
	public long timeMillis;
	/** How the cost basis was resolved: {@code "direct"}, {@code "set"} or {@code "decant"} (null on legacy data). */
	public String basis;
	/** For a set flip, the component pieces consumed (their names, quantities and cost); null otherwise. */
	public List<FlipPiece> pieces;

	public Flip()
	{
	}

	public Flip(int itemId, String itemName, long quantity, long cost, long netProceeds, long timeMillis,
		String basis, List<FlipPiece> pieces)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.quantity = quantity;
		this.cost = cost;
		this.netProceeds = netProceeds;
		this.profit = netProceeds - cost;
		this.timeMillis = timeMillis;
		this.basis = basis;
		this.pieces = pieces;
	}
}

package com.runemargin.session;

/**
 * One component consumed by a set flip: the piece's name, the quantity used and its total
 * cost. Lets the History show what a sold set was actually assembled from.
 */
public class FlipPiece
{
	public String name;
	public long quantity;
	public long cost;

	public FlipPiece()
	{
	}

	public FlipPiece(String name, long quantity, long cost)
	{
		this.name = name;
		this.quantity = quantity;
		this.cost = cost;
	}
}

package com.runemargin.session;

import java.util.List;
import java.util.Set;

/**
 * An immutable summary of the current flipping session, handed to the UI. Built by
 * {@link SessionTracker#snapshot()} so the panel never touches live tracker state.
 */
public final class SessionSnapshot
{
	public final long realizedProfit;
	public final int flipCount;
	public final long taxPaid;
	public final long netProceeds;
	public final long costBasis;
	public final Long bestProfit;
	public final Long worstProfit;
	public final long sessionStartMillis;
	/** Cost still tied up in unsold buy lots. */
	public final long openInvested;
	/** Most-recent realized flips first (capped). */
	public final List<Flip> recentFlips;
	/** Most-recent raw buy/sell fills first (capped) — the browsable trade history. */
	public final List<Trade> recentTrades;
	/** Previously-finished sessions, newest first — archived on "New session". */
	public final List<SessionSummary> pastSessions;
	/** Item ids that still have an open cost basis (unsold buy lots / pooled potion doses). */
	public final Set<Integer> heldItemIds;

	SessionSnapshot(long realizedProfit, int flipCount, long taxPaid, long netProceeds, long costBasis,
		Long bestProfit, Long worstProfit, long sessionStartMillis, long openInvested, List<Flip> recentFlips,
		List<Trade> recentTrades, List<SessionSummary> pastSessions, Set<Integer> heldItemIds)
	{
		this.realizedProfit = realizedProfit;
		this.flipCount = flipCount;
		this.taxPaid = taxPaid;
		this.netProceeds = netProceeds;
		this.costBasis = costBasis;
		this.bestProfit = bestProfit;
		this.worstProfit = worstProfit;
		this.sessionStartMillis = sessionStartMillis;
		this.openInvested = openInvested;
		this.recentFlips = recentFlips;
		this.recentTrades = recentTrades;
		this.pastSessions = pastSessions;
		this.heldItemIds = heldItemIds;
	}

	/** Realized ROI as a percentage of matched cost, or null if nothing sold yet. */
	public Double roiPct()
	{
		if (costBasis <= 0)
		{
			return null;
		}
		return realizedProfit * 100.0 / costBasis;
	}
}

package com.runemargin.session;

/**
 * A finished flipping session, archived when the player starts a new one. Just the
 * headline figures needed to review past performance — the individual flips/trades of
 * a closed session are not retained. All gp figures are whole coins; {@link #profit}
 * is realized, after-tax.
 */
public class SessionSummary
{
	public long startMillis;
	public long endMillis;
	public long profit;
	public int flipCount;
	/** Matched cost basis, for the ROI figure. */
	public long costBasis;
	public long taxPaid;

	public SessionSummary()
	{
	}

	public SessionSummary(long startMillis, long endMillis, long profit, int flipCount, long costBasis, long taxPaid)
	{
		this.startMillis = startMillis;
		this.endMillis = endMillis;
		this.profit = profit;
		this.flipCount = flipCount;
		this.costBasis = costBasis;
		this.taxPaid = taxPaid;
	}

	/** Realized ROI as a percentage of matched cost, or null if nothing was sold. */
	public Double roiPct()
	{
		return costBasis <= 0 ? null : profit * 100.0 / costBasis;
	}
}

package com.runemargin.session;

import com.google.gson.Gson;
import com.runemargin.RuneMarginConfig;
import com.runemargin.calc.GeTax;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * Tracks the player's realized flipping profit for the current session.
 *
 * <p>Fills are fed in as they complete ({@link #recordBuy}/{@link #recordSell}); a sell is
 * matched against earlier buys and profit is booked after GE tax (via {@link GeTax}, the
 * same source of truth as the website). Three cost-basis paths are tried, in order:
 *
 * <ul>
 *   <li><b>Direct</b> — FIFO against buy lots of the same item (a plain flip).</li>
 *   <li><b>Set</b> — selling an assembled set is costed against the buy lots of its
 *       component pieces (one of each per set), so "buy the pieces, sell the set" is one
 *       flip. Recipes come from {@link #setSetRecipes}.</li>
 *   <li><b>Decant</b> — potions are pooled by dose: buying a {@code (n)} potion adds
 *       {@code n} doses to its family, and selling a {@code (m)} potion consumes {@code m}
 *       doses. So "buy (3)s, decant, sell (4)s" is tracked against the doses you paid for.</li>
 * </ul>
 *
 * <p>Every path only books the quantity actually covered by tracked buys — if you sell two
 * sets but only bought pieces for one, the second (from your bank) has no known cost basis
 * and is left out of profit (though it still appears in the trade log).
 *
 * <p>State is persisted per RuneScape name through {@link ConfigManager}. The core is free
 * of RuneLite types so it can be unit-tested without a client; the plugin translates
 * {@code GrandExchangeOfferChanged} events into {@code recordBuy}/{@code recordSell} calls.
 */
@Slf4j
@Singleton
public class SessionTracker
{
	private static final int MAX_RECENT_FLIPS = 100;
	private static final int MAX_RECENT_TRADES = 200;
	private static final int MAX_PAST_SESSIONS = 30;
	private static final String KEY_PREFIX = "session_";

	// Matches a potion/dose name like "Prayer potion(4)" -> family "Prayer potion", dose 4.
	private static final Pattern DOSE_PATTERN = Pattern.compile("^(.*?)\\((\\d)\\)$");

	private final ConfigManager configManager;
	private final Gson gson;
	@Nullable
	private final ItemManager itemManager;

	private final CopyOnWriteArrayList<Consumer<SessionSnapshot>> listeners = new CopyOnWriteArrayList<>();

	// Reference data, not persisted: set recipes (set item id -> component item ids, one
	// entry per piece needed) and a name cache used to detect potions. Both are populated
	// by the plugin; tests inject them directly.
	private Map<Integer, List<Integer>> setRecipes = new HashMap<>();
	private final Map<Integer, String> knownNames = new HashMap<>();

	@Nullable
	private String profile;
	private State state = new State();

	@Inject
	public SessionTracker(ConfigManager configManager, Gson gson, ItemManager itemManager)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.itemManager = itemManager;
	}

	/** Test constructor: no persistence, no name resolution. */
	public SessionTracker()
	{
		this(null, null, null);
	}

	/**
	 * Bind to a player. Loads that player's persisted session (if any). A no-op when
	 * the profile is unchanged.
	 */
	public synchronized void setProfile(@Nullable String rsn)
	{
		if (rsn == null || rsn.equals(profile))
		{
			return;
		}
		profile = rsn;
		state = load(rsn);
		if (state.sessionStartMillis == 0)
		{
			state.sessionStartMillis = System.currentTimeMillis();
		}
		notifyListeners();
	}

	/** Provide the set recipes (set item id -> component item ids) used to cost set sells. */
	public synchronized void setSetRecipes(@Nullable Map<Integer, List<Integer>> recipes)
	{
		setRecipes = recipes != null ? recipes : new HashMap<>();
	}

	/** Test/plugin seam: seed a known item name so potion detection works without a client. */
	synchronized void putItemName(int itemId, String name)
	{
		knownNames.put(itemId, name);
	}

	/** Record a completed buy fill of {@code qty} units for {@code spent} total gp. */
	public synchronized void recordBuy(int itemId, long qty, long spent)
	{
		if (qty <= 0)
		{
			return;
		}
		ensureStarted();
		PotionInfo pot = potionInfo(itemId);
		if (pot != null)
		{
			// Potions are pooled by dose so a decant (buy (3), sell (4)) still costs out.
			state.dosePool.computeIfAbsent(pot.family, k -> new ArrayList<>())
				.add(new DoseLot(pot.dose * qty, spent));
		}
		else
		{
			state.inventory.computeIfAbsent(itemId, k -> new ArrayList<>()).add(new Lot(qty, spent));
		}
		recordTrade(itemId, Trade.Side.BUY, qty, spent);
		persist();
		notifyListeners();
	}

	/**
	 * Record a completed sell fill of {@code qty} units for {@code grossSpent} total gp
	 * (the pre-tax sale value). The cost basis is resolved via the direct, set or decant
	 * path (see the class doc), and after-tax profit is booked for the matched quantity.
	 * Unmatched quantity (sold without a tracked basis) is ignored for profit.
	 */
	public synchronized void recordSell(int itemId, long qty, long grossSpent)
	{
		if (qty <= 0)
		{
			return;
		}
		ensureStarted();

		// GE tax is 2% of the per-item sale price (see GeTax), computed ourselves rather
		// than trusting the raw offer value, to stay consistent with the website.
		long salePrice = grossSpent / qty;
		long taxTotal = GeTax.geTax(salePrice) * qty;

		Match match;
		String basis;
		List<FlipPiece> pieces = null;
		PotionInfo pot = potionInfo(itemId);
		if (pot != null)
		{
			match = consumeDoses(pot.family, pot.dose, qty);
			basis = "decant";
		}
		else if (setRecipes.containsKey(itemId))
		{
			pieces = new ArrayList<>();
			match = consumeSet(itemId, qty, pieces);
			basis = "set";
		}
		else
		{
			match = consumeDirect(itemId, qty);
			basis = "direct";
		}

		if (match.qty > 0)
		{
			// Proceeds and tax apportioned to the matched quantity.
			long matchedGross = grossSpent * match.qty / qty;
			long matchedTax = taxTotal * match.qty / qty;
			long matchedNet = matchedGross - matchedTax;

			Flip flip = new Flip(itemId, resolveName(itemId), match.qty, match.cost, matchedNet,
				System.currentTimeMillis(), basis, pieces);

			state.flips.add(flip);
			if (state.flips.size() > MAX_RECENT_FLIPS)
			{
				state.flips.remove(0);
			}
			state.flipCount++;
			state.realizedProfit += flip.profit;
			state.netProceeds += matchedNet;
			state.costBasis += match.cost;
			state.taxPaid += matchedTax;
			state.bestProfit = state.bestProfit == null ? flip.profit : Math.max(state.bestProfit, flip.profit);
			state.worstProfit = state.worstProfit == null ? flip.profit : Math.min(state.worstProfit, flip.profit);
		}

		// The full sell is booked to trade history (the listing price the player achieved),
		// even the unmatched part — it still tells them what they sold at.
		recordTrade(itemId, Trade.Side.SELL, qty, grossSpent);
		persist();
		notifyListeners();
	}

	/** Direct FIFO match against buy lots of {@code itemId}. Mutates the lots consumed. */
	private Match consumeDirect(int itemId, long qty)
	{
		List<Lot> lots = state.inventory.get(itemId);
		long matchedQty = 0;
		long matchedCost = 0;
		while (lots != null && !lots.isEmpty() && matchedQty < qty)
		{
			Lot lot = lots.get(0);
			long take = Math.min(lot.qty, qty - matchedQty);
			long costForTake = lot.spent * take / lot.qty;
			lot.qty -= take;
			lot.spent -= costForTake;
			matchedQty += take;
			matchedCost += costForTake;
			if (lot.qty <= 0)
			{
				lots.remove(0);
			}
		}
		if (lots != null && lots.isEmpty())
		{
			state.inventory.remove(itemId);
		}
		return new Match(matchedQty, matchedCost);
	}

	/**
	 * Cost a set sell against its component buy lots: each set consumes one of every piece,
	 * so the number of sets we can cost is limited by the scarcest piece. Anything beyond
	 * that (assembled from bank stock) is left unmatched.
	 */
	private Match consumeSet(int setId, long qty, List<FlipPiece> outPieces)
	{
		List<Integer> comps = setRecipes.get(setId);
		if (comps == null || comps.isEmpty())
		{
			return new Match(0, 0);
		}
		Map<Integer, Long> need = new HashMap<>();
		for (int c : comps)
		{
			need.merge(c, 1L, Long::sum);
		}
		long coverable = qty;
		for (Map.Entry<Integer, Long> e : need.entrySet())
		{
			long avail = totalQty(state.inventory.get(e.getKey()));
			coverable = Math.min(coverable, avail / e.getValue());
		}
		if (coverable <= 0)
		{
			return new Match(0, 0);
		}
		long cost = 0;
		for (Map.Entry<Integer, Long> e : need.entrySet())
		{
			Match m = consumeDirect(e.getKey(), coverable * e.getValue());
			cost += m.cost;
			if (outPieces != null)
			{
				outPieces.add(new FlipPiece(resolveName(e.getKey()), m.qty, m.cost));
			}
		}
		return new Match(coverable, cost);
	}

	/**
	 * Cost a potion sell against the family's dose pool: selling {@code qty} {@code (dose)}
	 * potions needs {@code dose * qty} doses. Only whole potions covered by pooled doses are
	 * matched (the rest are basis-less bank stock).
	 */
	private Match consumeDoses(String family, int dose, long qty)
	{
		List<DoseLot> lots = state.dosePool.get(family);
		if (lots == null || lots.isEmpty())
		{
			return new Match(0, 0);
		}
		long available = 0;
		for (DoseLot lot : lots)
		{
			available += lot.doses;
		}
		long covered = Math.min(qty, available / dose);
		if (covered <= 0)
		{
			return new Match(0, 0);
		}
		long needDoses = covered * dose;
		long taken = 0;
		long cost = 0;
		while (!lots.isEmpty() && taken < needDoses)
		{
			DoseLot lot = lots.get(0);
			long take = Math.min(lot.doses, needDoses - taken);
			long costForTake = lot.cost * take / lot.doses;
			lot.doses -= take;
			lot.cost -= costForTake;
			taken += take;
			cost += costForTake;
			if (lot.doses <= 0)
			{
				lots.remove(0);
			}
		}
		if (lots.isEmpty())
		{
			state.dosePool.remove(family);
		}
		return new Match(covered, cost);
	}

	private static long totalQty(@Nullable List<Lot> lots)
	{
		if (lots == null)
		{
			return 0;
		}
		long q = 0;
		for (Lot lot : lots)
		{
			q += lot.qty;
		}
		return q;
	}

	/** Append a raw fill to the browsable trade history (most-recent kept, capped). */
	private void recordTrade(int itemId, Trade.Side side, long qty, long total)
	{
		state.trades.add(new Trade(itemId, resolveName(itemId), side, qty, total, System.currentTimeMillis()));
		if (state.trades.size() > MAX_RECENT_TRADES)
		{
			state.trades.remove(0);
		}
	}

	/**
	 * Start a fresh session for the current profile. The outgoing session, if it had any
	 * activity, is archived to {@link State#pastSessions}.
	 *
	 * <p>Open buy lots and the dose pool are <b>carried forward</b>: they are the cost basis
	 * of items you still hold, just as valid after a reset. Only the realized-P&amp;L
	 * counters and the trade log start fresh.
	 */
	public synchronized void reset()
	{
		List<SessionSummary> past = state.pastSessions != null ? state.pastSessions : new ArrayList<>();
		if (state.flipCount > 0 || !state.trades.isEmpty())
		{
			long end = System.currentTimeMillis();
			past.add(0, new SessionSummary(state.sessionStartMillis, end, state.realizedProfit,
				state.flipCount, state.costBasis, state.taxPaid));
			while (past.size() > MAX_PAST_SESSIONS)
			{
				past.remove(past.size() - 1);
			}
		}
		Map<Integer, List<Lot>> heldLots = state.inventory;   // still-held cost basis survives
		Map<String, List<DoseLot>> heldDoses = state.dosePool; // as do pooled potion doses
		state = new State();
		state.pastSessions = past;
		state.inventory = heldLots;
		state.dosePool = heldDoses;
		state.sessionStartMillis = System.currentTimeMillis();
		persist();
		notifyListeners();
	}

	/**
	 * Average unit cost of {@code itemId} still held this session, or {@code null} if none
	 * is tracked. Handles potions (from the dose pool) and sets (the summed cost of one of
	 * each held component), so the overlay can show the real buy price on a sell offer.
	 */
	public synchronized Long avgBuyPrice(int itemId)
	{
		PotionInfo pot = potionInfo(itemId);
		if (pot != null)
		{
			List<DoseLot> lots = state.dosePool.get(pot.family);
			if (lots == null || lots.isEmpty())
			{
				return null;
			}
			long doses = 0;
			long cost = 0;
			for (DoseLot lot : lots)
			{
				doses += lot.doses;
				cost += lot.cost;
			}
			return doses > 0 ? (cost * pot.dose) / doses : null;
		}
		if (setRecipes.containsKey(itemId))
		{
			long total = 0;
			for (int c : setRecipes.get(itemId))
			{
				Long piece = avgBuyPrice(c);
				if (piece == null)
				{
					return null; // can't cost the set without every piece
				}
				total += piece;
			}
			return total;
		}
		List<Lot> lots = state.inventory.get(itemId);
		if (lots == null || lots.isEmpty())
		{
			return null;
		}
		long qty = 0;
		long spent = 0;
		for (Lot lot : lots)
		{
			qty += lot.qty;
			spent += lot.spent;
		}
		return qty > 0 ? spent / qty : null;
	}

	public synchronized SessionSnapshot snapshot()
	{
		long openInvested = 0;
		Set<Integer> heldItemIds = new HashSet<>();
		for (Map.Entry<Integer, List<Lot>> e : state.inventory.entrySet())
		{
			long qty = 0;
			for (Lot lot : e.getValue())
			{
				openInvested += lot.spent;
				qty += lot.qty;
			}
			if (qty > 0)
			{
				heldItemIds.add(e.getKey());
			}
		}
		// Potions are pooled by dose family; mark every known potion item of a family that
		// still has doses as "held", so its History row reads as holding, not consumed.
		Set<String> familiesWithDoses = new HashSet<>();
		for (Map.Entry<String, List<DoseLot>> e : state.dosePool.entrySet())
		{
			long doses = 0;
			for (DoseLot lot : e.getValue())
			{
				openInvested += lot.cost;
				doses += lot.doses;
			}
			if (doses > 0)
			{
				familiesWithDoses.add(e.getKey());
			}
		}
		if (!familiesWithDoses.isEmpty())
		{
			for (Integer id : new ArrayList<>(knownNames.keySet()))
			{
				PotionInfo p = potionInfo(id);
				if (p != null && familiesWithDoses.contains(p.family))
				{
					heldItemIds.add(id);
				}
			}
		}

		List<Flip> recent = new ArrayList<>(state.flips);
		Collections.reverse(recent);

		List<Trade> trades = new ArrayList<>(state.trades);
		Collections.reverse(trades);

		// pastSessions is already newest-first (reset() prepends).
		List<SessionSummary> past = new ArrayList<>(state.pastSessions);

		return new SessionSnapshot(state.realizedProfit, state.flipCount, state.taxPaid, state.netProceeds,
			state.costBasis, state.bestProfit, state.worstProfit, state.sessionStartMillis, openInvested, recent,
			trades, past, heldItemIds);
	}

	public void addListener(Consumer<SessionSnapshot> listener)
	{
		listeners.add(listener);
	}

	public void removeListener(Consumer<SessionSnapshot> listener)
	{
		listeners.remove(listener);
	}

	private void ensureStarted()
	{
		if (state.sessionStartMillis == 0)
		{
			state.sessionStartMillis = System.currentTimeMillis();
		}
	}

	private void notifyListeners()
	{
		if (listeners.isEmpty())
		{
			return;
		}
		SessionSnapshot snap = snapshot();
		for (Consumer<SessionSnapshot> listener : listeners)
		{
			listener.accept(snap);
		}
	}

	/** Potion family + dose for an item whose name looks like "Foo(n)" (n = 1..4), else null. */
	@Nullable
	private PotionInfo potionInfo(int itemId)
	{
		String name = resolveName(itemId);
		if (name == null)
		{
			return null;
		}
		Matcher m = DOSE_PATTERN.matcher(name.trim());
		if (!m.matches())
		{
			return null;
		}
		int dose = m.group(2).charAt(0) - '0';
		if (dose < 1 || dose > 4)
		{
			return null; // real potion doses are 1-4; excludes charge/jewellery "(n)" items
		}
		String family = m.group(1).trim();
		return family.isEmpty() ? null : new PotionInfo(family, dose);
	}

	@Nullable
	private String resolveName(int itemId)
	{
		String known = knownNames.get(itemId);
		if (known != null)
		{
			return known;
		}
		if (itemManager == null)
		{
			return null;
		}
		try
		{
			String name = itemManager.getItemComposition(itemId).getName();
			knownNames.put(itemId, name);
			return name;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private void persist()
	{
		if (configManager == null || gson == null || profile == null)
		{
			return;
		}
		try
		{
			configManager.setConfiguration(RuneMarginConfig.GROUP, KEY_PREFIX + profile, gson.toJson(state));
		}
		catch (RuntimeException e)
		{
			log.debug("Failed to persist session state", e);
		}
	}

	private State load(String rsn)
	{
		if (configManager == null || gson == null)
		{
			return new State();
		}
		try
		{
			String json = configManager.getConfiguration(RuneMarginConfig.GROUP, KEY_PREFIX + rsn);
			if (json != null && !json.isEmpty())
			{
				State loaded = gson.fromJson(json, State.class);
				if (loaded != null)
				{
					loaded.normalize();
					return loaded;
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Failed to load session state for {}", rsn, e);
		}
		return new State();
	}

	/** A remaining buy lot: {@code qty} units bought for {@code spent} total gp. */
	private static final class Lot
	{
		long qty;
		long spent;

		@SuppressWarnings("unused") // Gson
		Lot()
		{
		}

		Lot(long qty, long spent)
		{
			this.qty = qty;
			this.spent = spent;
		}
	}

	/** A remaining pool of potion doses: {@code doses} doses bought for {@code cost} gp. */
	private static final class DoseLot
	{
		long doses;
		long cost;

		@SuppressWarnings("unused") // Gson
		DoseLot()
		{
		}

		DoseLot(long doses, long cost)
		{
			this.doses = doses;
			this.cost = cost;
		}
	}

	/** A potion's family (name without the dose suffix) and its dose count. */
	private static final class PotionInfo
	{
		final String family;
		final int dose;

		PotionInfo(String family, int dose)
		{
			this.family = family;
			this.dose = dose;
		}
	}

	/** The outcome of a cost-basis match: units covered and their total cost. */
	private static final class Match
	{
		final long qty;
		final long cost;

		Match(long qty, long cost)
		{
			this.qty = qty;
			this.cost = cost;
		}
	}

	/** The full persisted session state. */
	private static final class State
	{
		Map<Integer, List<Lot>> inventory = new HashMap<>();
		Map<String, List<DoseLot>> dosePool = new HashMap<>();
		List<Flip> flips = new ArrayList<>();
		List<Trade> trades = new ArrayList<>();
		List<SessionSummary> pastSessions = new ArrayList<>();
		long realizedProfit;
		long netProceeds;
		long costBasis;
		long taxPaid;
		int flipCount;
		Long bestProfit;
		Long worstProfit;
		long sessionStartMillis;

		/** Guard against nulls after a partial/legacy deserialization. */
		void normalize()
		{
			if (inventory == null)
			{
				inventory = new HashMap<>();
			}
			if (dosePool == null)
			{
				dosePool = new HashMap<>();
			}
			if (flips == null)
			{
				flips = new ArrayList<>();
			}
			if (trades == null)
			{
				trades = new ArrayList<>();
			}
			if (pastSessions == null)
			{
				pastSessions = new ArrayList<>();
			}
		}
	}
}

package com.runemargin.session;

/**
 * One completed GE fill — a raw buy or sell the player transacted this session,
 * kept as a browsable trade history so they can see what they last paid / sold at
 * and decide what price to chase. Prices are the GE listing price (pre-tax): a
 * sell's {@link #unitPrice} is what the offer was set to, not the post-tax take.
 */
public class Trade
{
	public enum Side
	{
		BUY,
