	private void renderRows(JPanel list, JLabel status, List<ItemRow> rows)
	{
		list.removeAll();
		if (rows == null || rows.isEmpty())
		{
			status.setText("No results.");
		}
		else
		{
			status.setText(rows.size() + " items");
			Consumer<ItemRow> onClick = this::onSelect;
			boolean first = true;
			for (ItemRow row : rows)
			{
				if (!first)
				{
					list.add(spacer());
				}
				list.add(new FlipRowPanel(row, itemManager, onClick));
				first = false;
			}
		}
		list.revalidate();
		list.repaint();
	}

	/**
	 * React to an access-token change: the caller's tier (and therefore the profit cap
	 * on the flips they can see) may have changed, so refresh both.
	 */
	public void onAccessTokenChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			loadFlips();
			loadTier();
			loadWatchlist();
		});
	}

	/** Re-fetch the lists with the current membership (P2P/F2P) filter applied. */
	public void reloadLists()
	{
		SwingUtilities.invokeLater(() ->
		{
			loadFlips();
			if (!searchField.getText().trim().isEmpty())
			{
				runSearch();
			}
			// Sets and Decant filter client-side, so re-fetch them too — otherwise a
			// membership change wouldn't re-apply while one of those tabs is open.
			loadSets();
			loadDecant();
		});
	}

	private void loadTier()
	{
		api.tier(
			status -> SwingUtilities.invokeLater(() -> updateTierBanner(status)),
			err -> SwingUtilities.invokeLater(() -> updateTierBanner(null)));
	}

	private static final Color BANNER_BG = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color BANNER_BG_HOVER = ColorScheme.DARK_GRAY_HOVER_COLOR;

	/**
	 * Render the subscription banner: a quiet confirmation for Pro/Supporter, or an
	 * upgrade nudge (with the profit cap that's currently hiding the biggest flips)
	 * for everyone below. Clickable banners spell out that they open the website and
	 * show a link-styled, underlined call-to-action.
	 */
	private void updateTierBanner(TierStatus status)
	{
		tierBanner.removeAll();
		clearMouseListeners(tierBanner);
		if (status == null)
		{
			// Couldn't resolve tier (offline / API down): don't show a misleading banner.
			tierBanner.setVisible(false);
			tierBanner.revalidate();
			tierBanner.repaint();
			return;
		}

		String tier = status.effectiveTier == null ? "anon" : status.effectiveTier;
		boolean unlimited = "pro".equals(tier) || "supporter".equals(tier);
		boolean tokenSet = config.accessToken() != null && !config.accessToken().trim().isEmpty();

		final String statusText;
		final String ctaText; // null == not clickable
		final Color accent;
		final String openUrl;
		if (unlimited)
		{
			statusText = ("supporter".equals(tier) ? "♛ Supporter — all flips unlocked"
				: "★ Pro — all flips unlocked");
			ctaText = null;
			accent = Brand.GOLD_BRIGHT;
			openUrl = null;
		}
		else if (tokenSet && !status.authenticated)
		{
			// A token is configured but the server didn't accept it (wrong token, or
			// used from a different IP than it was locked to).
			statusText = "Access token not active";
			ctaText = "Check it on runemargin.co.uk →";
			accent = LOSS;
			openUrl = SITE_URL + "/account";
		}
		else
		{
			String cap = status.cap == null ? null : Format.gp(status.cap);
			statusText = cap == null ? tierLabel(tier)
				: tierLabel(tier) + " — flips over " + cap + " hidden";
			ctaText = "Upgrade to Pro on runemargin.co.uk →";
			accent = GOLD;
			openUrl = SITE_URL + "/pricing";
		}

		JLabel label = new JLabel(bannerHtml(statusText, ctaText, accent));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));

		tierBanner.setBackground(BANNER_BG);
		tierBanner.add(label, BorderLayout.CENTER);
		if (openUrl != null)
		{
			tierBanner.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			tierBanner.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					LinkBrowser.browse(openUrl);
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					tierBanner.setBackground(BANNER_BG_HOVER);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					tierBanner.setBackground(BANNER_BG);
				}
			});
		}
		else
		{
			tierBanner.setCursor(Cursor.getDefaultCursor());
		}
		tierBanner.setVisible(true);
		tierBanner.revalidate();
		tierBanner.repaint();
	}

	/**
	 * Two-line banner markup: the status line, and (when clickable) an underlined,
	 * link-coloured call-to-action naming the website. A fixed width makes the label
	 * wrap in the narrow panel instead of truncating with an ellipsis.
	 */
	private static String bannerHtml(String statusText, String ctaText, Color accent)
	{
		String hex = toHex(accent);
		StringBuilder sb = new StringBuilder("<html><div style='width:168px'>");
		sb.append("<font color='").append(hex).append("'>").append(statusText).append("</font>");
		if (ctaText != null)
		{
			sb.append("<br><font color='").append(hex).append("'><u>")
				.append(ctaText).append("</u></font>");
		}
		return sb.append("</div></html>").toString();
	}

	private static String toHex(Color c)
	{
		return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	private static void clearMouseListeners(JPanel panel)
	{
		for (MouseListener existing : panel.getMouseListeners())
		{
			panel.removeMouseListener(existing);
		}
	}

	private static String tierLabel(String tier)
	{
		switch (tier)
		{
			case "free":
				return "Free plan";
			case "basic":
				return "Basic plan";
			default:
				return "Free view"; // anon / unknown
		}
	}

	/**
	 * Re-apply the configured sort to the already-fetched rows and re-render, without
	 * a network round-trip. Called when the user changes the sort in settings.
	 */
	public void reSort()
	{
		SwingUtilities.invokeLater(() ->
		{
			List<ItemRow> sortedFlips = sortRows(lastFlips);
			renderRows(flipsList, flipsStatus, sortedFlips);
			updateTopFlip(sortedFlips);
			renderRows(searchList, searchStatus, sortRows(lastSearch));
			if (!lastWatch.isEmpty())
			{
				renderRows(watchList, watchStatus, sortRows(lastWatch));
			}
		});
	}

	/** A copy of {@code rows} ordered by the configured {@link SortMode} (highest first). */
	private List<ItemRow> sortRows(List<ItemRow> rows)
	{
		if (rows == null || rows.isEmpty())
		{
			return List.of();
		}
		SortMode mode = config.sortMode();
		List<ItemRow> sorted = new ArrayList<>(rows);
		// Highest value first; rows missing the metric sink to the bottom.
		sorted.sort(Comparator.comparing(
			row -> sortKey(row, mode),
			Comparator.nullsLast(Comparator.reverseOrder())));
		return sorted;
	}

	/** The numeric sort key for a row under {@code mode}, or null if unavailable. */
	private static Double sortKey(ItemRow row, SortMode mode)
	{
		switch (mode)
		{
			case RM_SCORE:
				return row.stats == null || row.stats.flipScore == null ? null : row.stats.flipScore.doubleValue();
			case MARGIN:
				return row.margin == null ? null : row.margin.doubleValue();
			case ROI:
				return row.roiPct;
			case POTENTIAL_PROFIT:
				return row.potentialProfit == null ? null : row.potentialProfit.doubleValue();
			case VOLUME_24H:
				return row.stats == null || row.stats.vol24h == null ? null : row.stats.vol24h.doubleValue();
			case REALISTIC_PROFIT:
			default:
				if (row.stats != null && row.stats.realisticProfit != null)
				{
					return row.stats.realisticProfit.doubleValue();
				}
				// Fall back to potential profit so the default order is still sensible
				// when the volume-aware figure is absent.
				return row.potentialProfit == null ? null : row.potentialProfit.doubleValue();
		}
	}

	private void onSelect(ItemRow row)
	{
		overlay.setItem(row);
	}

	/** Focus the in-game overlay on a set play (its buy-the-pieces breakdown). */
	private void onSelectSet(SetRow row)
	{
		overlay.setSet(row);
	}

	/** Focus the in-game overlay on a decant play (what dose to buy). */
	private void onSelectDecant(DecantRow row)
	{
		overlay.setDecant(row);
	}

	private static JPanel listContainer()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return p;
	}

	private static Component spacer()
	{
		JPanel s = new JPanel();
		s.setBackground(ColorScheme.DARK_GRAY_COLOR);
		s.setPreferredSize(new Dimension(0, 4));
		s.setMaximumSize(new Dimension(Integer.MAX_VALUE, 4));
		return s;
	}

	private static JScrollPane wrapScroll(Component view)
	{
		// North-align the list so rows stack from the top rather than centring, and
		// track the viewport width so rows never exceed the visible area — otherwise the
		// viewport sizes to the content's preferred width and clips the right edge (the
		// score pill) since horizontal scrolling is disabled.
		JPanel north = new WidthTrackingPanel(new BorderLayout());
		north.setBackground(ColorScheme.DARK_GRAY_COLOR);
		north.add(view, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(north);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		// Kill the default white viewport that shows through below north-aligned content.
		scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		return scroll;
	}

	/**
	 * A scroll view that always matches the viewport's width (so rows are constrained to
	 * the visible area and wide content is truncated, not clipped off-screen) while still
	 * scrolling vertically to its own preferred height.
	 */
	private static final class WidthTrackingPanel extends JPanel implements Scrollable
	{
		WidthTrackingPanel(java.awt.LayoutManager layout)
		{
			super(layout);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(java.awt.Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(java.awt.Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.runemargin.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The 0–100 Rune Margin score as a colour-banded pill, matching the website's
 * {@code ScoreBadge}: ≥80 green, ≥60 lime, ≥40 amber, else red; hover shows the
 * score reasons. Painted with a translucent rounded background over the row.
 */
class ScorePill extends JLabel
{
	// Floor width so a 1–3 digit score always has room and the row's EAST slot can
	// never collapse to zero (which would hide the pill entirely).
	private static final int MIN_WIDTH = 26;

	private final Color pillBg;

	ScorePill(Integer score, List<String> reasons)
	{
		super(score == null ? "—" : score.toString(), SwingConstants.CENTER);
		setFont(FontManager.getRunescapeSmallFont().deriveFont(java.awt.Font.BOLD));
		setOpaque(false);
		setBorder(BorderFactory.createEmptyBorder(1, 7, 1, 7));

		if (score == null)
		{
			setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			pillBg = null;
			return;
		}

		Band band = bandFor(score);
		setForeground(band.fg);
		pillBg = band.bg;
		if (reasons != null && !reasons.isEmpty())
		{
			setToolTipText(String.join(" • ", reasons));
		}
	}

	@Override
	public Dimension getPreferredSize()
	{
		Dimension d = super.getPreferredSize();
		d.width = Math.max(d.width, MIN_WIDTH);
		return d;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		if (pillBg != null)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(pillBg);
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), 8, 8);
			g2.dispose();
		}
		super.paintComponent(g);
	}

	private static Band bandFor(int score)
	{
		if (score >= 80)
		{
			return new Band(new Color(0x3F, 0xBF, 0x6F), new Color(63, 191, 111, 110));
		}
		if (score >= 60)
		{
			return new Band(new Color(0xA7, 0xC8, 0x5A), new Color(160, 200, 90, 100));
		}
		if (score >= 40)
		{
			return new Band(new Color(0xF0, 0xB1, 0x32), new Color(240, 177, 50, 100));
		}
		return new Band(new Color(0xE0, 0x52, 0x4A), new Color(224, 82, 74, 100));
	}

	private static final class Band
	{
		final Color fg;
		final Color bg;

		Band(Color fg, Color bg)
		{
			this.fg = fg;
			this.bg = bg;
		}
	}
}

package com.runemargin.ui;

import com.runemargin.session.Flip;
import com.runemargin.session.SessionSnapshot;
import com.runemargin.session.SessionSummary;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.GridLayout;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The Session tab: a prominent realized-profit "hero", supporting stats, and a
 * scrollable list of recent realized flips. All updates arrive via
 * {@link #update(SessionSnapshot)} on the EDT.
 */
class SessionPanel extends JPanel
{
	private static final Color ACCENT = Brand.GOLD; // Rune Margin brand gold
	private static final Color GAIN = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color LOSS = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("d MMM, HH:mm", Locale.ENGLISH);

	private final ItemManager itemManager;
	private final JPanel flipList = new JPanel();
	private final JPanel pastList = new JPanel();

	private final JLabel heroProfit = new JLabel("0");
	private final JLabel roiValue = subStat();
	private final JLabel perHourValue = subStat();
	private final JLabel flipsValue = subStat();

	private final JLabel taxValue = statValue();
	private final JLabel bestValue = statValue();
	private final JLabel worstValue = statValue();
	private final JLabel investedValue = statValue();

	SessionPanel(ItemManager itemManager, Runnable onReset)
	{
		this.itemManager = itemManager;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(10, 8, 8, 8));

		add(fill(buildHero()));
		add(Box.createVerticalStrut(8));
		add(fill(buildStats()));
		add(Box.createVerticalStrut(8));
		add(fill(buildResetButton(onReset)));
		add(Box.createVerticalStrut(10));
		add(fill(sectionHeader("Recent flips")));
		add(Box.createVerticalStrut(4));

		flipList.setLayout(new BoxLayout(flipList, BoxLayout.Y_AXIS));
		flipList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		flipList.setAlignmentX(LEFT_ALIGNMENT);
		add(flipList);

		add(Box.createVerticalStrut(10));
		add(fill(sectionHeader("Past sessions")));
		add(Box.createVerticalStrut(4));
		pastList.setLayout(new BoxLayout(pastList, BoxLayout.Y_AXIS));
		pastList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pastList.setAlignmentX(LEFT_ALIGNMENT);
		add(pastList);
	}

	private JPanel buildHero()
	{
		JPanel card = card(new BorderLayout(0, 2));

		JLabel caption = new JLabel("SESSION PROFIT");
		caption.setForeground(MUTED);
		caption.setFont(FontManager.getRunescapeSmallFont());

		heroProfit.setForeground(Color.WHITE);
		heroProfit.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 22f));

		JPanel subRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		subRow.setBackground(card.getBackground());
		subRow.add(roiValue);
		subRow.add(separator());
		subRow.add(perHourValue);
		subRow.add(separator());
		subRow.add(flipsValue);

		card.add(caption, BorderLayout.NORTH);
		card.add(heroProfit, BorderLayout.CENTER);
		card.add(subRow, BorderLayout.SOUTH);
		return card;
	}

	private JPanel buildStats()
	{
		JPanel card = card(new GridLayout(0, 2, 8, 6));
		card.add(statCaption("Tax paid"));
		card.add(taxValue);
		card.add(statCaption("Best flip"));
		card.add(bestValue);
		card.add(statCaption("Worst flip"));
		card.add(worstValue);
		card.add(statCaption("Invested"));
		card.add(investedValue);
		return card;
	}

	private JButton buildResetButton(Runnable onReset)
	{
		JButton reset = new JButton("New session");
		reset.setHorizontalAlignment(SwingConstants.CENTER);
		reset.setFocusPainted(false);
		reset.setFont(FontManager.getRunescapeSmallFont());
		reset.setForeground(Color.WHITE);
		reset.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		reset.setBorder(BorderFactory.createEmptyBorder(7, 10, 7, 10));
		reset.addActionListener(e -> onReset.run());
		return reset;
	}

	void update(SessionSnapshot s)
	{
		heroProfit.setText(signed(s.realizedProfit));
		heroProfit.setForeground(profitColor(s.realizedProfit));

		roiValue.setText("ROI " + Format.pct(s.roiPct()));
		perHourValue.setText(Format.gp(perHour(s)) + "/hr");
		flipsValue.setText(s.flipCount + (s.flipCount == 1 ? " flip" : " flips"));

		taxValue.setText(Format.gp(s.taxPaid));
		setSignedStat(bestValue, s.bestProfit);
		setSignedStat(worstValue, s.worstProfit);
		investedValue.setText(Format.gp(s.openInvested));

		flipList.removeAll();
		if (s.recentFlips.isEmpty())
		{
			JLabel empty = new JLabel("No completed flips yet.");
			empty.setForeground(MUTED);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));
			empty.setAlignmentX(LEFT_ALIGNMENT);
			flipList.add(empty);
		}
		else
		{
			boolean first = true;
			for (Flip flip : s.recentFlips)
			{
				if (!first)
				{
					flipList.add(Box.createVerticalStrut(4));
				}
				flipList.add(fill(flipRow(flip)));
				first = false;
			}
		}
		flipList.revalidate();
		flipList.repaint();

		pastList.removeAll();
		if (s.pastSessions.isEmpty())
		{
			JLabel empty = new JLabel("No past sessions yet.");
			empty.setForeground(MUTED);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));
			empty.setAlignmentX(LEFT_ALIGNMENT);
			pastList.add(empty);
		}
		else
		{
			boolean first = true;
			for (SessionSummary summary : s.pastSessions)
			{
				if (!first)
				{
					pastList.add(Box.createVerticalStrut(4));
				}
				pastList.add(fill(pastRow(summary)));
				first = false;
			}
		}
		pastList.revalidate();
		pastList.repaint();
	}

	private JPanel pastRow(SessionSummary s)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 8));

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		JLabel when = new JLabel(DATE_FORMAT.format(new Date(s.endMillis)));
		when.setFont(FontManager.getRunescapeSmallFont());
		when.setForeground(Color.WHITE);

		String flips = s.flipCount + (s.flipCount == 1 ? " flip" : " flips");
		JLabel detail = new JLabel(flips + " · ROI " + Format.pct(s.roiPct())
			+ " · " + duration(s.startMillis, s.endMillis));
		detail.setFont(FontManager.getRunescapeSmallFont());
		detail.setForeground(MUTED);

		text.add(when);
		text.add(detail);
		row.add(text, BorderLayout.CENTER);

		JLabel profit = new JLabel(signed(s.profit));
		profit.setFont(FontManager.getRunescapeSmallFont());
		profit.setForeground(profitColor(s.profit));
		row.add(profit, BorderLayout.EAST);
		return row;
	}

	private static String duration(long startMillis, long endMillis)
	{
		long mins = Math.max(0, (endMillis - startMillis) / 60000);
		if (mins < 60)
		{
			return mins + "m";
		}
		return (mins / 60) + "h " + (mins % 60) + "m";
	}

	private JPanel flipRow(Flip flip)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 8));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		AsyncBufferedImage image = itemManager.getImage(flip.itemId, (int) Math.max(1, flip.quantity), flip.quantity > 1);
		image.addTo(icon);
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		JLabel name = new JLabel(flip.itemName != null ? flip.itemName : "Item " + flip.itemId);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);

		JLabel detail = new JLabel("x" + Format.exact(flip.quantity) + " · " + Format.gp(flip.netProceeds) + " in");
		detail.setFont(FontManager.getRunescapeSmallFont());
		detail.setForeground(MUTED);

		text.add(name);
		text.add(detail);
		row.add(text, BorderLayout.CENTER);

		JLabel profit = new JLabel(signed(flip.profit));
		profit.setFont(FontManager.getRunescapeSmallFont());
		profit.setForeground(profitColor(flip.profit));
		row.add(profit, BorderLayout.EAST);
		return row;
	}

	private void setSignedStat(JLabel label, Long value)
	{
		label.setText(value == null ? "—" : signed(value));
		label.setForeground(value == null ? Color.WHITE : profitColor(value));
	}

	private static long perHour(SessionSnapshot s)
	{
		long elapsed = Math.max(1L, System.currentTimeMillis() - s.sessionStartMillis);
		return Math.round(s.realizedProfit / (elapsed / 3_600_000.0));
	}

	private static String signed(long v)
	{
		return (v > 0 ? "+" : "") + Format.gp(v);
	}

	private static Color profitColor(long v)
	{
		if (v == 0)
		{
			return MUTED;
		}
		return v > 0 ? GAIN : LOSS;
	}

	// --- small builders / layout helpers ---------------------------------------

	private static JPanel card(java.awt.LayoutManager layout)
	{
		JPanel p = new JPanel(layout);
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createEmptyBorder(9, 10, 9, 10));
		return p;
	}

	private static JLabel sectionHeader(String text)
	{
		JLabel l = new JLabel(text);
		l.setForeground(ACCENT);
		l.setFont(FontManager.getRunescapeSmallFont());
		return l;
	}

	private static JLabel separator()
	{
		JLabel l = new JLabel("   ·   ");
		l.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		l.setFont(FontManager.getRunescapeSmallFont());
		return l;
	}

	private static JLabel subStat()
	{
		JLabel l = new JLabel("—");
		l.setForeground(MUTED);
		l.setFont(FontManager.getRunescapeSmallFont());
		return l;
	}

	private static JLabel statCaption(String text)
	{
		JLabel l = new JLabel(text);
		l.setForeground(MUTED);
		l.setFont(FontManager.getRunescapeSmallFont());
		return l;
	}

	private static JLabel statValue()
	{
		JLabel l = new JLabel("0");
		l.setForeground(Color.WHITE);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setHorizontalAlignment(SwingConstants.RIGHT);
		return l;
	}

	/** Make a component fill the panel width under BoxLayout (Y) and left-align it. */
	private static <T extends JComponent> T fill(T c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		// Zero minimum width so the row shrinks to the panel width (BoxLayout otherwise
		// honours the row's minimum — the full CENTER text — and clips the EAST figure).
		c.setMinimumSize(new Dimension(0, 0));
		return c;
	}
}

package com.runemargin.ui;

import com.runemargin.api.SetRow;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridBagLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * One item-set play: the set icon, name, the better direction (combine/break) with its
 * after-tax profit / ROI, and the Rune Margin score. Clicking focuses the in-game
 * overlay on the set (via {@code onClick}), which lists the pieces to buy.
 */
class SetRowPanel extends JPanel
{
	SetRowPanel(SetRow row, ItemManager itemManager, Consumer<SetRow> onClick)
	{
		setLayout(new BorderLayout(6, 0));
		setBorder(Brand.card(5));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		AsyncBufferedImage image = itemManager.getImage(row.setId);
		image.addTo(icon);
		add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(getBackground());

		JLabel name = new JLabel(row.setName == null ? "Set " + row.setId : row.setName);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);

		boolean combine = !"break".equalsIgnoreCase(row.bestDirection);
		Double roi = combine ? row.combineRoi : row.breakRoi;
		JLabel figures = new JLabel(direction(row.bestDirection) + " · +" + Format.gp(row.bestProfit)
			+ " · " + Format.pct(roi));
		figures.setFont(FontManager.getRunescapeSmallFont());
		figures.setForeground(profitColor(row.bestProfit));

		JLabel sub = new JLabel(row.pieceCount + " pieces · ~" + Format.gp(row.realisticProfit) + "/day");
		sub.setFont(FontManager.getRunescapeSmallFont());
		sub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		text.add(name);
		text.add(figures);
		text.add(sub);
		add(text, BorderLayout.CENTER);

		// Rune Margin score pill, matching the flip rows.
		JComponent pillWrap = new JPanel(new GridBagLayout());
		pillWrap.setOpaque(false);
		pillWrap.add(new ScorePill(row.rmScore, null));
		add(pillWrap, BorderLayout.EAST);

		// Allow the row to shrink to the panel width so the EAST pill isn't clipped
		// (see FlipRowPanel).
		setMinimumSize(new Dimension(0, 0));

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onClick.accept(row);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
				text.setBackground(getBackground());
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setBackground(ColorScheme.DARKER_GRAY_COLOR);
				text.setBackground(getBackground());
			}
		});
	}

	private static String direction(String dir)
	{
		return "break".equalsIgnoreCase(dir) ? "BREAK" : "COMBINE";
	}

	private static Color profitColor(Integer v)
	{
		if (v == null)
		{
			return ColorScheme.LIGHT_GRAY_COLOR;
		}
		return v >= 0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR;
	}
}

package com.runemargin.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The Slots tab: a live view of the player's Grand Exchange offers — buy/sell, item, how far
 * each has filled (a progress bar) and the offer price. Fed immutable {@link GeSlot}
 * snapshots from the plugin via {@link #update(List)} on the EDT.
 */
class SlotsPanel extends JPanel
{
	private static final Color BUY = new Color(0x4A, 0x9B, 0xE0);  // blue — gp going out
	private static final Color SELL = Brand.GOLD;                  // gold — gp coming in
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;

	private final ItemManager itemManager;
	private final JPanel list = new JPanel();

	SlotsPanel(ItemManager itemManager)
	{
		this.itemManager = itemManager;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(10, 8, 8, 8));

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setAlignmentX(LEFT_ALIGNMENT);
		add(list);

		update(List.of());
	}

	/** Rebuild the list from the latest slot snapshot. Empty slots are dropped. */
	void update(List<GeSlot> slots)
	{
		list.removeAll();
		boolean any = false;
		if (slots != null)
		{
			for (GeSlot s : slots)
			{
				if (s == null)
				{
					continue;
				}
				if (any)
				{
					list.add(Box.createVerticalStrut(6));
				}
				list.add(fill(card(s)));
				any = true;
			}
		}
		if (!any)
		{
			JLabel empty = new JLabel("No active GE offers.");
			empty.setForeground(MUTED);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));
			empty.setAlignmentX(LEFT_ALIGNMENT);
			list.add(empty);
		}
		list.revalidate();
		list.repaint();
	}

	private JPanel card(GeSlot s)
	{
		Color accent = s.buy ? BUY : SELL;

		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(Brand.card(6));

		// Header: direction on the left, offer status on the right.
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(card.getBackground());
		header.setAlignmentX(LEFT_ALIGNMENT);
		JLabel dir = new JLabel(s.buy ? "Buy" : "Sell");
		dir.setFont(FontManager.getRunescapeBoldFont());
		dir.setForeground(accent);
		JLabel state = new JLabel(statusText(s));
		state.setFont(FontManager.getRunescapeSmallFont());
		state.setForeground(statusColor(s));
		header.add(dir, BorderLayout.WEST);
		header.add(state, BorderLayout.EAST);

		// Body: icon + name / quantity.
		JPanel body = new JPanel(new BorderLayout(6, 0));
		body.setBackground(card.getBackground());
		body.setAlignmentX(LEFT_ALIGNMENT);
		body.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		AsyncBufferedImage image = itemManager.getImage(s.itemId);
		image.addTo(icon);
		body.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(card.getBackground());
		JLabel name = new JLabel(s.name);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);
		JLabel qty = new JLabel(Format.exact(s.sold) + " / " + Format.exact(s.total));
		qty.setFont(FontManager.getRunescapeSmallFont());
		qty.setForeground(MUTED);
		text.add(name);
		text.add(qty);
		body.add(text, BorderLayout.CENTER);

		// Progress bar — green when complete, gold while filling.
		Bar bar = new Bar(s.fraction(), s.complete() ? Brand.UP : Brand.GOLD);

		JLabel price = new JLabel(Format.exact(s.price) + " coins");
		price.setFont(FontManager.getRunescapeSmallFont());
		price.setForeground(MUTED);
		price.setAlignmentX(LEFT_ALIGNMENT);
		price.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));

		card.add(header);
		card.add(body);
		card.add(bar);
		card.add(price);
		return card;
	}

	private static String statusText(GeSlot s)
	{
		switch (s.status)
		{
			case FILLED:
				return "filled";
			case CANCELLED:
				return "cancelled";
			default:
				return s.buy ? "buying" : "selling";
		}
	}

	private static Color statusColor(GeSlot s)
	{
		switch (s.status)
		{
			case FILLED:
				return Brand.UP;
			case CANCELLED:
				return MUTED;
			default:
				return MUTED;
		}
	}

	/** Left-align a component and let it fill the panel width under the vertical BoxLayout. */
	private static <T extends JComponent> T fill(T c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		c.setMinimumSize(new Dimension(0, 0));
		return c;
	}

	/** A slim rounded progress bar filled to {@code frac} in {@code fill}. */
	private static final class Bar extends JComponent
	{
		private final double frac;
		private final Color fill;

		Bar(double frac, Color fill)
		{
			this.frac = Math.max(0, Math.min(1, frac));
			this.fill = fill;
			setPreferredSize(new Dimension(0, 9));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 9));
			setAlignmentX(LEFT_ALIGNMENT);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			g2.setColor(ColorScheme.SCROLL_TRACK_COLOR);
			g2.fillRoundRect(0, 0, w - 1, h - 1, h, h);
			int fw = (int) Math.round((w - 2) * frac);
			if (fw > 0)
			{
				g2.setColor(fill);
				g2.fillRoundRect(1, 1, fw, h - 3, h, h);
			}
			g2.dispose();
		}
	}
}

package com.runemargin.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The Session profit-target bar: a grey progress fill inside a gold border while you climb
 * toward the goal, flipping to a glowing gold fill once you hit 100%. Cosmetic only — the
 * confetti celebration is handled at the panel level by {@link ConfettiLayer}.
 */
class TargetProgressBar extends JComponent
{
	private static final int HEIGHT = 20;
	private static final Color TRACK = ColorScheme.SCROLL_TRACK_COLOR;
	private static final Color PROGRESS = new Color(0x8A, 0x8A, 0x8A);

	private double frac;
	private boolean done;

	TargetProgressBar()
	{
		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	/**
	 * Update the fill for {@code current}/{@code target} gp. Returns {@code true} the first
	 * time an update crosses into "reached", so the caller can fire the confetti once.
	 */
	boolean setProgress(long current, long target)
	{
		boolean wasDone = done;
		double f = target > 0 ? (double) current / target : 0;
		done = f >= 1.0;
		frac = Math.max(0, Math.min(f, 1.0));
		repaint();
		return done && !wasDone;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		int arc = h;

		// Track.
		g2.setColor(TRACK);
		g2.fillRoundRect(0, 0, w - 1, h - 1, arc, arc);

		// Fill — grey while climbing, gold once the goal is reached.
		int fillW = (int) Math.round((w - 2) * frac);
		if (fillW > 0)
		{
			g2.setColor(done ? Brand.GOLD_BRIGHT : PROGRESS);
			g2.fillRoundRect(1, 1, fillW, h - 3, arc, arc);
		}

		// Gold border, always — brighter and thicker once reached (a subtle "glow").
		g2.setStroke(new BasicStroke(done ? 2f : 1.4f));
		g2.setColor(done ? Brand.GOLD_BRIGHT : Brand.GOLD);
		g2.drawRoundRect(1, 1, w - 3, h - 3, arc, arc);

		// Centred caption.
		String text = done ? "Target reached!" : Math.round(frac * 100) + "%";
		g2.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g2.getFontMetrics();
		int tx = (w - fm.stringWidth(text)) / 2;
		int ty = (h + fm.getAscent() - fm.getDescent()) / 2;
		g2.setColor(done ? new Color(0x20, 0x18, 0x08) : Color.WHITE);
		g2.drawString(text, tx, ty);
		g2.dispose();
	}
}

package com.runemargin.ui;

import com.runemargin.session.Flip;
import com.runemargin.session.FlipPiece;
import com.runemargin.session.SessionSnapshot;
import com.runemargin.session.Trade;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The History tab: a per-item trade log of this session's completed buys and sells,
 * so the player can see what they last paid / sold at and decide what price to chase.
 * One row per item (most recently traded first) showing its latest buy and sell.
 */
class TradeHistoryPanel extends JPanel
{
	private static final Color GAIN = ColorScheme.PROGRESS_COMPLETE_COLOR; // gp coming in / profit
	private static final Color LOSS = ColorScheme.PROGRESS_ERROR_COLOR;    // a real, realized loss
	private static final Color BOUGHT = Brand.PARCHMENT;                   // buy info — neutral, not a loss
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;

	private final ItemManager itemManager;
	private final JPanel list = new JPanel();

	TradeHistoryPanel(ItemManager itemManager)
	{
		this.itemManager = itemManager;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(10, 8, 8, 8));

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setAlignmentX(LEFT_ALIGNMENT);
		add(list);
	}

	void update(SessionSnapshot s)
	{
		list.removeAll();

		// recentTrades is newest-first; group by item preserving that order, so the
		// most recently traded items lead and each item keeps its latest fills.
		Map<Integer, ItemHistory> byItem = new LinkedHashMap<>();
		for (Trade t : s.recentTrades)
		{
			ItemHistory h = byItem.computeIfAbsent(t.itemId, k -> new ItemHistory(t.itemId, t.itemName));
			if (t.side == Trade.Side.BUY && h.lastBuy == null)
			{
				h.lastBuy = t;
			}
			else if (t.side == Trade.Side.SELL && h.lastSell == null)
			{
				h.lastSell = t;
			}
		}

		// Realized flips per item (matched buy→sell, after tax) — the only figures we
		// can honestly call profit. A sell with no entry here has no known cost basis.
		Map<Integer, FlipAgg> realized = new HashMap<>();
		for (Flip f : s.recentFlips)
		{
			realized.computeIfAbsent(f.itemId, k -> new FlipAgg()).add(f);
		}

		// Names of every piece a set flip consumed this session — so a piece's own row can
		// read "used in a set" rather than looking like it's still held.
		Set<String> setPieceNames = new HashSet<>();
		for (FlipAgg agg : realized.values())
		{
			if ("set".equals(agg.basis))
			{
				setPieceNames.addAll(agg.pieces.keySet());
			}
		}
		Set<Integer> held = s.heldItemIds != null ? s.heldItemIds : new HashSet<>();

		if (byItem.isEmpty())
		{
			JLabel empty = new JLabel("No trades yet this session.");
			empty.setForeground(MUTED);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));
			empty.setAlignmentX(LEFT_ALIGNMENT);
			list.add(empty);
		}
		else
		{
			List<ItemHistory> items = new ArrayList<>(byItem.values());
			boolean first = true;
			for (ItemHistory h : items)
			{
				if (!first)
				{
					list.add(Box.createVerticalStrut(4));
				}
				list.add(fill(itemRow(h, realized.get(h.itemId), held, setPieceNames)));
				first = false;
			}
		}

		list.revalidate();
		list.repaint();
	}

	private JPanel itemRow(ItemHistory h, FlipAgg flip, Set<Integer> held, Set<String> setPieceNames)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 8));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		AsyncBufferedImage image = itemManager.getImage(h.itemId);
		image.addTo(icon);
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		JLabel name = new JLabel(h.itemName != null ? h.itemName : "Item " + h.itemId);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);

		boolean hasBasis = flip != null && flip.quantity > 0;
		text.add(name);
		text.add(buyLabel(h.lastBuy, flip));
		text.add(sellLabel(h.lastSell, hasBasis));
		text.add(profitLabel(h, flip, held, setPieceNames));

		// For a set flip, spell out the pieces it was assembled from and their cost, so the
		// set's cost basis isn't a mystery number disconnected from the pieces you bought.
		if (flip != null && !flip.pieces.isEmpty())
		{
			for (Map.Entry<String, long[]> e : flip.pieces.entrySet())
			{
				long qty = e.getValue()[0];
				long cost = e.getValue()[1];
				JLabel piece = small();
				String q = qty > 1 ? " ×" + Format.exact(qty) : "";
				piece.setText("· " + e.getKey() + q + " · " + Format.gp(cost));
				piece.setForeground(MUTED);
				text.add(piece);
			}
		}
		row.add(text, BorderLayout.CENTER);
		return row;
	}

	/** The buy line: this session's fill, else the cost basis implied by a matched flip
	 *  (a purchase from an earlier session), else nothing tracked. */
	private static JLabel buyLabel(Trade buy, FlipAgg flip)
	{
		JLabel l = small();
		if (buy != null)
		{
			l.setText("Bought " + Format.gp(buy.unitPrice) + " ea · x" + Format.exact(buy.quantity)
				+ " · " + Format.timeAgo(buy.timeMillis));
			l.setForeground(BOUGHT);
		}
		else if (flip != null && flip.quantity > 0)
		{
			// A flip with no direct buy of this item id: a set (bought as pieces), a decant
			// (bought as doses), or a same-item buy carried in from an earlier session.
			String note;
			if ("set".equals(flip.basis))
			{
				note = "from pieces";
			}
			else if ("decant".equals(flip.basis))
			{
				note = "from doses";
			}
			else
			{
				note = "earlier session";
			}
			l.setText("Bought ~" + Format.gp(flip.cost / flip.quantity) + " ea · " + note);
			l.setForeground(BOUGHT);
		}
		else
		{
			l.setText("Bought — no fills");
			l.setForeground(MUTED);
		}
		return l;
	}

	/** The sell line. Green only when a cost basis exists, so a bank sell (unknown cost)
	 *  never reads as profit. */
	private static JLabel sellLabel(Trade sell, boolean hasBasis)
	{
		JLabel l = small();
		if (sell == null)
		{
			l.setText("Sold — no fills");
			l.setForeground(MUTED);
			return l;
		}
		l.setText("Sold " + Format.gp(sell.unitPrice) + " ea · x" + Format.exact(sell.quantity)
			+ " · " + Format.timeAgo(sell.timeMillis));
		l.setForeground(hasBasis ? GAIN : MUTED);
		return l;
	}

	/** The bottom line: realized after-tax profit when matched, a "no cost basis" note for
	 *  bank stock, a "used in a set/decant" note for a buy consumed into another flip, or a
	 *  holding note for a buy still sitting in inventory. */
	private static JLabel profitLabel(ItemHistory h, FlipAgg flip, Set<Integer> held, Set<String> setPieceNames)
	{
		JLabel l = small();
		if (flip != null && flip.quantity > 0)
		{
			l.setText("Profit " + signed(flip.profit) + " · after tax");
			l.setForeground(flip.profit >= 0 ? GAIN : LOSS);
		}
		else if (h.lastSell != null)
		{
			l.setText("No cost basis · sold from stock");
			l.setForeground(MUTED);
		}
		else if (held.contains(h.itemId))
		{
			l.setText("Holding · not sold yet");
			l.setForeground(MUTED);
		}
		else
		{
			// Bought, never sold under its own id, and no longer held — it was consumed into
			// a set (a piece) or a decant (a dose).
			boolean inSet = h.itemName != null && setPieceNames.contains(h.itemName);
			l.setText("Used in a " + (inSet ? "set" : "decant"));
			l.setForeground(MUTED);
		}
		return l;
	}

	private static JLabel small()
	{
		JLabel l = new JLabel();
		l.setFont(FontManager.getRunescapeSmallFont());
		return l;
	}

	private static String signed(long v)
	{
		return (v > 0 ? "+" : "") + Format.gp(v);
	}

	/** Make a component fill the panel width under BoxLayout (Y) and left-align it. */
	private static <T extends JComponent> T fill(T c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		// Zero minimum width so rows shrink to the panel width rather than overflowing.
		c.setMinimumSize(new Dimension(0, 0));
		return c;
	}

	/** The latest buy and sell we've seen for a single item this session. */
	private static final class ItemHistory
	{
		final int itemId;
		final String itemName;
		Trade lastBuy;
		Trade lastSell;

		ItemHistory(int itemId, String itemName)
		{
			this.itemId = itemId;
			this.itemName = itemName;
		}
	}

	/** This session's realized flips for one item, summed: matched quantity, cost basis,
	 *  after-tax profit, how it was costed, and (for sets) the pieces consumed. */
	private static final class FlipAgg
	{
		long quantity;
		long cost;
		long profit;
		String basis;
		/** Consumed set pieces, summed by name: {@code name -> {quantity, cost}}. */
		final Map<String, long[]> pieces = new LinkedHashMap<>();

		void add(Flip f)
		{
			quantity += f.quantity;
			cost += f.cost;
			profit += f.profit;
			if (f.basis != null)
			{
				basis = f.basis;
			}
			if (f.pieces != null)
			{
				for (FlipPiece p : f.pieces)
				{
					long[] agg = pieces.computeIfAbsent(p.name != null ? p.name : "?", k -> new long[2]);
					agg[0] += p.quantity;
					agg[1] += p.cost;
				}
			}
		}
	}
}

package com.runemargin;

import com.runemargin.calc.GeTax;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class GeTaxTest
{
	@Test
	public void exemptBelowFifty()
	{
		assertEquals(0, GeTax.geTax(0));
		assertEquals(0, GeTax.geTax(49));
	}

	@Test
	public void twoPercentFloored()
	{
		assertEquals(1, GeTax.geTax(50));    // floor(50 * 0.02) = 1
		assertEquals(2, GeTax.geTax(100));   // floor(100 * 0.02) = 2
		assertEquals(30, GeTax.geTax(1540)); // floor(1540 * 0.02) = 30
	}

	@Test
	public void cappedAtFiveMillion()
	{
		// 2% of 500m would be 10m, but the cap holds it at 5m.
		assertEquals(GeTax.CAP, GeTax.geTax(500_000_000));
	}

	@Test
	public void nonFiniteIsZero()
	{
		assertEquals(0, GeTax.geTax(Double.NaN));
		assertEquals(0, GeTax.geTax(Double.NEGATIVE_INFINITY));
	}
}

